import { BinarySchemaNode } from "./BinarySchemaNode";
export class BinarySchema {
    nodeMap = new Map();
    nodes = [];
    constructor(schema) {
        for (const node of schema) {
            const newNode = new BinarySchemaNode(node);
            this.nodes.push(newNode);
            this.nodeMap.set(node.name, newNode);
        }
    }
    _value = 0;
    toStateString() {
        if (!this.nodes.length)
            return "*";
        let stateString = [];
        for (let i = 0; i < this.nodes.length; i++) {
            stateString.push(`${this.nodes[i].name}=${String(this.get(this.nodes[i].name))}`);
        }
        return stateString.join(",");
    }
    readString(stateString) {
        if (stateString == "*")
            return 0;
        const split = stateString.split(",");
        let ecnoded = 0;
        for (const pair of split) {
            const [key, v] = pair.split("=");
            if (v == "*")
                continue;
            const node = this.nodeMap.get(key);
            if (!node)
                continue;
            if (node.valuePalette) {
                const value = node.valuePalette.getNumberId(v);
                if (value === undefined)
                    throw new Error(`Binary schema string node value with id ${v} does not exist.`);
                ecnoded = node.setValue(ecnoded, value);
            }
            else {
                ecnoded = node.setValue(ecnoded, Number(v));
            }
        }
        return ecnoded;
    }
    fromStateObject(stateObject) {
        let encodedValue = 0;
        for (let i = 0; i < stateObject.length; i += 2) {
            const key = stateObject[i];
            if (typeof key !== "string")
                continue;
            const value = stateObject[i + 1];
            const node = this.nodeMap.get(key);
            if (!node)
                continue;
            if (typeof value == "string") {
                if (!node.valuePalette)
                    continue;
                encodedValue = node.setValue(encodedValue, node.valuePalette.getNumberId(value) || 0);
                continue;
            }
            encodedValue = node.setValue(encodedValue, value);
        }
        return encodedValue;
    }
    getStateObject(stateValue) {
        const stateArray = [];
        for (const node of this.nodes) {
            if (node.valuePalette) {
                stateArray.push(node.name, node.valuePalette.getStringId(node.getValue(stateValue)));
                continue;
            }
            stateArray.push(node.name, node.getValue(stateValue));
        }
        return stateArray;
    }
    compareString(stateString, ecnoded) {
        if (stateString == "*")
            return true;
        const split = stateString.split(",");
        for (const pair of split) {
            const [key, v] = pair.split("=");
            if (v == "*")
                continue;
            const node = this.nodeMap.get(key);
            if (!node)
                continue;
            if (node.valuePalette) {
                const value = node.valuePalette.getNumberId(v);
                if (value === undefined)
                    throw new Error(`Binary schema string node value  with id ${key} does not exist.`);
                if (node.getValue(ecnoded) !== value) {
                    return false;
                }
            }
            else {
                if (node.getValue(ecnoded) !== Number(v)) {
                    return false;
                }
            }
        }
        return true;
    }
    startEncoding(value = 0) {
        this._value = value;
        return this;
    }
    get(id) {
        const node = this.nodeMap.get(id);
        if (!node)
            throw new Error(`Node with ${id} does not exist.`);
        if (node.valuePalette)
            return node.valuePalette.getStringId(node.getValue(this._value));
        return node.getValue(this._value);
    }
    getNumber(id) {
        const node = this.nodeMap.get(id);
        if (!node)
            throw new Error(`Node with ${id} does not exist.`);
        return node.getValue(this._value);
    }
    getValue(id) {
        const node = this.nodeMap.get(id);
        if (!node)
            throw new Error(`Node with ${id} does not exist.`);
        if (!node.valuePalette)
            throw new Error(`Node with ${id} does not have a value palette.`);
        return node.valuePalette.getStringId(node.getValue(this._value));
    }
    setNumber(id, value) {
        const node = this.nodeMap.get(id);
        if (!node)
            throw new Error(`Node with ${id} does not exist.`);
        this._value = node.setValue(this._value, value);
        return this;
    }
    setValue(id, value) {
        const node = this.nodeMap.get(id);
        if (!node)
            throw new Error(`Node with ${id} does not exist.`);
        if (!node.valuePalette)
            throw new Error(`Node with ${id} does not have a value palette.`);
        this._value = node.setValue(this._value, node.valuePalette.getNumberId(value));
        return this;
    }
    getEncoded() {
        return this._value;
    }
    getSchema() {
        return this.nodes.map((_) => _.data);
    }
    totalStates() {
        if (this.nodes.length === 0)
            return 1;
        let total = 1;
        for (const node of this.nodes) {
            if (node.data.values) {
                total *= node.data.values.length;
            }
            else {
                total *= node.bitMask + 1;
            }
        }
        return total;
    }
}
